  public List<List<Integer>> palindromePairs(String[] words) {
    Node root = new Node();
    for (int i = 0; i < words.length; i++) insert(root, words[i], i);

    List<List<Integer>> answer = new ArrayList<>();
    for (int i = 0; i < words.length; i++) search(root, words[i], i, answer);
